\title{Holographic Coding Geometry: A Finite, Formally Verified Bridge\\
Between Quantum Information and Emergent Spacetime}
\author{Aristotle}
\date{2026-06-20}

\begin{document}
\maketitle

\begin{abstract}
We develop a finite, fully rigorous algebraic model of the ``spacetime as a quantum
error-correcting code'' paradigm and of the emergence of geometry from random tensor
networks. The model assigns to each region $X$ of a finite boundary an entropy
$S(X)$, an effective area $\area(X)$, and a distance proxy, subject to normalization,
nonnegativity, entropy submodularity (strong subadditivity), the Ryu--Takayanagi
relation $S(X)=\area(X)/4$, and a Singleton-type bound $S(X)\le|X|$. Within this model
we define the \emph{syndrome defect} $\defect(X,Y)=S(X)+S(Y)-S(X\cap Y)-S(X\cup Y)$ as a
discrete curvature functional and prove it is nonnegative. Our central result is a
\emph{cross-domain equivalence}: entropy submodularity holds universally if and only if
area submodularity does, with the Ryu--Takayanagi relation as the explicit translation;
quantitatively the syndrome defect equals one quarter of the area defect. We recast the
Singleton bound as a lower bound on logical content, prove that bulk reconstruction is
monotone under enlargement of the boundary region, and---in a companion tropical
(min-plus) model---prove that entanglement-wedge membership is stable under metric
perturbation and that boundary observations determine the bulk on the wedge. Finally we
model the random-tensor-network encoding threshold via a strictly monotone critical bond
dimension. All results are theorems verified in the Lean~4 proof assistant; here we
present their statements with mathematical proof sketches.
\end{abstract}

\section{Introduction}
The holographic principle asserts that the physics of a region of spacetime (the
\emph{bulk}) is encoded on its lower-dimensional \emph{boundary}. Its sharpest modern
incarnations---AdS/CFT, tensor-network models, and the ``spacetime is a quantum
error-correcting code'' program---suggest that smooth geometry is emergent from the
entanglement structure of an underlying quantum system. Two pillars recur: the
\emph{Ryu--Takayanagi (RT) relation} $S(X)=\area(\gamma_X)/4G$, and \emph{strong
subadditivity (SSA)} of entropy. We isolate the finite combinatorial core of these
statements and prove them with complete rigor, so that ``geometry is information'' and
``spacetime is a code'' become theorems. We complement the entropy/area model with a
tropical (min-plus) model of entanglement-wedge reconstruction and a minimal model of
the random-tensor-network encoding threshold. All statements are formally verified in
Lean~4 with Mathlib.

\section{The Holographic Code Profile}

\begin{definition}[Holographic code profile]
Let $\alpha$ be a type with decidable equality, modeling finite boundary sites. A
\emph{holographic code profile} on $\alpha$ consists of functionals
$S, \area, \dist : \mathrm{Finset}(\alpha) \to \Reals$ such that:
\begin{itemize}
  \item \textbf{Normalization:} $S(\varnothing)=0$, $\area(\varnothing)=0$.
  \item \textbf{Nonnegativity:} $S(X), \area(X), \dist(X) \ge 0$ for all $X$.
  \item \textbf{Submodularity (SSA):} $S(X)+S(Y) \ge S(X\cap Y)+S(X\cup Y)$ for all $X,Y$.
  \item \textbf{Ryu--Takayanagi:} $S(X) = \area(X)/4$ for all $X$.
  \item \textbf{Singleton-like bound:} $S(X) \le |X|$ for all $X$.
\end{itemize}
\end{definition}

\begin{definition}[Syndrome defect]
For a profile $H$ and regions $X,Y$,
\[ \defect(X,Y) := S(X)+S(Y)-S(X\cap Y)-S(X\cup Y). \]
Zero defect signals entropic flatness (flat bulk geometry); positive defect signals a
curvature-like interaction.
\end{definition}

\section{Curvature is Nonnegative}

\begin{theorem}[\texttt{syndromeDefect\_nonneg}]
For every profile $H$ and all $X,Y$, $\ 0 \le \defect(X,Y)$.
\end{theorem}
\begin{proof}[Proof sketch]
Unfolding, the claim is exactly the submodularity axiom rearranged.
\end{proof}

\begin{theorem}[\texttt{strict\_submod\_of\_pos\_syndrome}]
If $0 < \defect(X,Y)$ then $S(X\cap Y)+S(X\cup Y) < S(X)+S(Y)$.
\end{theorem}

\begin{proposition}[Structural properties]
For all $X,Y$: $\defect(X,X)=0$ (\texttt{syndromeDefect\_self}); $\defect(X,Y)=\defect(Y,X)$
(\texttt{syndromeDefect\_symm}); $\defect(\varnothing,Y)=\defect(X,\varnothing)=0$
(\texttt{syndromeDefect\_empty\_left/right}).
\end{proposition}

\begin{proposition}[Special pairs]
If $X\cap Y=\varnothing$ then $\defect(X,Y)=S(X)+S(Y)-S(X\cup Y)$
(\texttt{syndromeDefect\_disjoint}); if $X\subseteq Y$ then $\defect(X,Y)=0$
(\texttt{syndromeDefect\_subset}).
\end{proposition}

\begin{proposition}[Cumulative nonnegativity]
For any list (\texttt{syndromeDefect\_list\_sum\_nonneg}) or finite set
(\texttt{syndromeDefect\_finset\_sum\_nonneg}) of region pairs, the sum of syndrome
defects is nonnegative.
\end{proposition}

\section{The Information--Geometry Bridge}

\begin{definition}[Area defect]
$\areaDefect(X,Y) := \area(X)+\area(Y)-\area(X\cap Y)-\area(X\cup Y)$.
\end{definition}

\begin{theorem}[\texttt{area\_submod\_of\_rt}]
$\area(X)+\area(Y) \ge \area(X\cap Y)+\area(X\cup Y)$ for all $X,Y$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply SSA to $S$, substitute $S=\area/4$ via RT, and cancel the factor of $4$.
\end{proof}

\begin{theorem}[\texttt{syndromeDefect\_eq\_area\_defect\_div\_four}]
$\defect(X,Y) = \areaDefect(X,Y)/4$; equivalently $\areaDefect(X,Y)=4\,\defect(X,Y)$.
\end{theorem}

\begin{corollary}[\texttt{areaDefect\_nonneg}, \texttt{areaDefect\_zero\_iff\_syndromeDefect\_zero}]
The area defect is nonnegative and vanishes iff the syndrome defect vanishes.
\end{corollary}

\begin{theorem}[Cross-domain equivalence, \texttt{rt\_submodularity\_iff\_area\_submodularity}]
For a profile $H$,
\[
\big(\forall X,Y:\ S(X)+S(Y)\ge S(X\cap Y)+S(X\cup Y)\big)
\iff
\big(\forall X,Y:\ \area(X)+\area(Y)\ge \area(X\cap Y)+\area(X\cup Y)\big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Each direction substitutes $S=\area/4$ and clears the constant; RT is precisely the
order isomorphism making the inequalities interchangeable.
\end{proof}

\begin{corollary}[Scaling laws]
$\area(X)=4\,S(X)$ (\texttt{area\_eq\_four\_S}); $\area(X)\le 4\,|X|$
(\texttt{area\_le\_four\_card}, a Bekenstein--Hawking-type bound);
$\area(X\cap Y)+\area(X\cup Y)\le\area(X)+\area(Y)$ (\texttt{area\_submodular}).
\end{corollary}

\section{Coding Bounds and Reconstruction}

\begin{definition}[Regional code bound]
Assigns to each region $X$ naturals $N(X)$ (physical qubits), $K(X)$ (logical qubits),
$D(X)$ (code distance) with the Singleton bound $N(X)-K(X)\le 2(D(X)-1)$.
\end{definition}

\begin{theorem}[\texttt{entropy\_lower\_bound\_of\_singleton}]
If $D(X)\ge 1$ then $K(X) \ge N(X) - 2(D(X)-1)$ in $\Ints$.
\end{theorem}

\begin{definition}[Code--geometry correspondence]
Couples a profile $H$ and a regional code bound $C$ with $S(X)=K(X)$ and $\area(X)=4K(X)$.
\end{definition}

\begin{theorem}[\texttt{correspondence\_rt\_consistent}]
Any such correspondence satisfies $S(X)=\area(X)/4$ automatically.
\end{theorem}

\begin{definition}[Reconstructable region]
Given a distance function $D$, $U$ is \emph{reconstructable} from $X$ if $U\subseteq X$
and $|U| < D(U)$.
\end{definition}

\begin{theorem}[Reconstruction monotonicity, \texttt{reconstructable\_monotone}]
If $U$ is reconstructable from $X$ and $X\subseteq Y$, then $U$ is reconstructable from $Y$.
\end{theorem}
\begin{proof}[Proof sketch]
Transitivity of $\subseteq$ gives $U\subseteq Y$; the condition $|U|<D(U)$ is unchanged.
\end{proof}

\begin{definition}[Laminar family]
$L$ is laminar if any two members are disjoint or nested.
\end{definition}

\begin{conjecture}[Saturation modularity, \texttt{SaturationModularityConjecture}]
If $S(X)=|X|$ on every member of a laminar family $L$, then $\defect(X,Y)=0$ for all
$X,Y\in L$.
\end{conjecture}
The nested case (\texttt{saturation\_conjecture\_nested}) and disjoint-saturated case
(\texttt{saturation\_conjecture\_disjoint\_saturated}) are proved unconditionally.

\section{Tropical Entanglement-Wedge Reconstruction}

Let $V$ carry a distance $d:V\times V\to\Reals$.

\begin{definition}[Distance to a region; wedge; observation]
For nonempty finite $s$, $\distToFinset(d,s,v)=\min_{b\in s} d(v,b)$. The wedge of a
boundary subset $B$ is
$W(B)=\{v\in\bulk : \distToFinset(d,B,v) < \distToFinset(d,\text{boundary}\setminus B,v)\}$.
For a bulk state $\varphi$, the boundary observation is
$\Obs_B(\varphi)(b)=\min_{v\in\bulk}(\varphi(v)+d(v,b))$.
\end{definition}

\begin{theorem}[\texttt{mem\_entanglementWedge\_iff}]
For $v\in\bulk$ with $B$ and $\text{boundary}\setminus B$ nonempty, $v\in W(B)$ iff
$\distToFinset(d,B,v) < \distToFinset(d,\text{boundary}\setminus B,v)$.
\end{theorem}

\begin{lemma}[\texttt{distToFinset\_perturb\_bound}]
If $|d(v,b)-d'(v,b)|<\varepsilon$ for all $b\in s$, then
$|\distToFinset(d,s,v)-\distToFinset(d',s,v)|<\varepsilon$.
\end{lemma}

\begin{theorem}[Wedge stability, \texttt{wedge\_membership\_stable\_under\_uniform\_perturbation}]
If $v\in W(B)$ under $d$ with margin $\delta$, and $d'$ satisfies
$|d(v,b)-d'(v,b)|<\varepsilon$ with $2\varepsilon<\delta$, then $v\in W(B)$ under $d'$.
\end{theorem}

\begin{lemma}[\texttt{boundaryObs\_eq\_of\_unique\_argmin}]
If $v$ is the strict unique minimizer of $w\mapsto\varphi(w)+d(w,b)$, then
$\Obs_B(\varphi)(b)=\varphi(v)+d(v,b)$.
\end{lemma}

\begin{theorem}[Surgery detectability, \texttt{wedge\_surgery\_detectable}]
If some $v$ is the unique argmin at some $b\in B$ for both $\varphi,\varphi'$ with
$\varphi'(v)\ne\varphi(v)$, then $\Obs_B(\varphi)$ and $\Obs_B(\varphi')$ differ at some
$b\in B$.
\end{theorem}

\begin{theorem}[Wedge reconstruction, \texttt{wedge\_reconstruction\_from\_boundary\_profiles}]
If every wedge point has a unique-argmin boundary witness in $B$ for each of
$\varphi,\varphi'$, and $\Obs_B(\varphi)=\Obs_B(\varphi')$ on all of $B$, then
$\varphi=\varphi'$ on $W(B)$.
\end{theorem}
\begin{proof}[Proof sketch]
Fix $v\in W(B)$ with witnesses $b,b'$. Uniqueness turns the relevant minima into
equalities; the general $\le$ bound covers cross terms. The four (in)equalities plus
equal observations force $\varphi(v)=\varphi'(v)$.
\end{proof}

\section{The Random-Tensor-Network Encoding Threshold}

\begin{definition}[Critical bond dimension, \texttt{critBond}]
$D_c(n) := 1 + n/10$. A length-$n$ chain is encodable by bond dimension $D$ exactly when
$D_c(n) < D$.
\end{definition}

\begin{theorem}[\texttt{critBond\_strictMono}]
$D_c$ is strictly increasing. Moreover $D_c(0)=1$ and $D_c(n+1)=D_c(n)+1/10$.
\end{theorem}

\section{Discussion and Future Work}
The factor of $4$ in RT is carried symbolically throughout, making the entropy/area
dictionary exact. Open directions: (C1) the non-differentiability locus of the
multi-surface entropy $\inf_i \area_i$ coincides with the tropical-variety corner locus,
with concave defect $\log D\cdot(\Delta\text{slope})\cdot t/2 + o(t)$ per corner; (C2)
$D_c(N)=\lceil \exp(\text{budget}(N)/\text{area})\rceil$ up to a constant; (C3)
$\log D$-Lipschitz min-cut entropy yields curvature bounded by a universal multiple of
$\log D$; (C4) concavity of $x\mapsto \log D\cdot\inf_i\area_i(x)$ survives surface
proliferation.

\section{Conclusion}
From normalization, nonnegativity, strong subadditivity, the Ryu--Takayanagi relation,
and a Singleton bound, we derived a nonnegative discrete curvature, an exact equivalence
between a quantum-information inequality and a geometric one, a coding bound linking area
to protected information, a monotone and stable wedge-refined reconstruction, and a
strictly increasing threshold for emergent geometry. In a clean finite setting, the
holographic dictionary is mathematics, not metaphor.

\end{document}

