function VERIFY-NONNEG-CURVATURE(sites, S):
    regions <- all subsets of sites
    worst <- +infinity
    ok <- true
    for X in regions:
        for Y in regions:
            d <- S(X) + S(Y) - S(X intersect Y) - S(X union Y)
            worst <- min(worst, d)
            if d < 0: ok <- false
    return (worst, ok)

