function ENTANGLEMENT-WEDGE(bulk, boundary, B, d):
    Bc <- boundary \ B
    wedge <- empty list
    for v in bulk:
        dB  <- min over b in B  of d[v,b]
        dBc <- min over b in Bc of d[v,b]
        if dB < dBc: append v to wedge
    return wedge

function WEDGE-STABLE-UNDER(bulk, boundary, B, d, d2):
    return ENTANGLEMENT-WEDGE(bulk,boundary,B,d)
         == ENTANGLEMENT-WEDGE(bulk,boundary,B,d2)
